import { describe, expect, test } from "bun:test";
import { parseSize } from "./size";

describe("parseSize", () => {
  test("parses bare bytes", () => {
    expect(parseSize("1B")).toBe(1);
    expect(parseSize("512B")).toBe(512);
    expect(parseSize("0B")).toBe(0);
  });

  test("parses KB/MB/GB using base-1024", () => {
    expect(parseSize("1KB")).toBe(1024);
    expect(parseSize("1MB")).toBe(1024 ** 2);
    expect(parseSize("1GB")).toBe(1024 ** 3);
    expect(parseSize("2KB")).toBe(2048);
  });

  test("parses decimal amounts", () => {
    expect(parseSize("1.5KB")).toBe(1536);
    expect(parseSize("0.5MB")).toBe(524288);
  });

  test("rounds fractional byte results", () => {
    expect(parseSize("1.5B")).toBe(2); // Math.round(1.5) -> 2
    expect(parseSize("1.333KB")).toBe(Math.round(1.333 * 1024));
  });

  test("is case-insensitive for units", () => {
    expect(parseSize("1kb")).toBe(1024);
    expect(parseSize("1Kb")).toBe(1024);
    expect(parseSize("1MB")).toBe(parseSize("1mb"));
    expect(parseSize("5b")).toBe(5);
  });

  test("tolerates surrounding whitespace and a space before the unit", () => {
    expect(parseSize("  1KB  ")).toBe(1024);
    expect(parseSize("1 KB")).toBe(1024);
    expect(parseSize(" 1 KB ")).toBe(1024);
  });

  test("throws on empty or whitespace-only input", () => {
    expect(() => parseSize("")).toThrow("invalid size: ");
    expect(() => parseSize("   ")).toThrow("invalid size:    ");
  });

  test("throws on missing unit", () => {
    expect(() => parseSize("100")).toThrow("invalid size: 100");
  });

  test("throws on unsupported unit", () => {
    expect(() => parseSize("1TB")).toThrow("invalid size: 1TB");
    expect(() => parseSize("1PB")).toThrow("invalid size: 1PB");
  });

  test("throws on missing amount", () => {
    expect(() => parseSize("KB")).toThrow("invalid size: KB");
  });

  test("throws on negative numbers", () => {
    expect(() => parseSize("-1KB")).toThrow("invalid size: -1KB");
  });

  test("throws on garbage input", () => {
    expect(() => parseSize("abc")).toThrow("invalid size: abc");
    expect(() => parseSize("1KB extra")).toThrow("invalid size: 1KB extra");
    expect(() => parseSize("1.2.3KB")).toThrow("invalid size: 1.2.3KB");
  });

  test("error message echoes the original input", () => {
    expect(() => parseSize("nonsense")).toThrow(/invalid size: nonsense/);
  });
});

